"""Extract v1.2.1 transport control flow, with deterministic boundary adapters.

This test records defects; successful exit means the OLD unsafe behavior was
reproduced. It is not a repaired-transport acceptance test or a game test.
"""
import argparse
import hashlib
import json
from pathlib import Path
from generate_buffer_contract_test import method

ROOT = Path(__file__).resolve().parents[1]
BASE_PATCH_SHA = '8ce8005da14ea40a4a10d6d7be848be05ce8ac9da25676667fa67820178b87e3'


def generate(source, output):
    util = source / 'bridge/src/util'
    header = (util / 'util_bridgecommand.h').read_text(encoding='utf-8')
    cpp = (util / 'util_bridgecommand.cpp').read_text(encoding='utf-8')
    start, end = method(cpp, 'DECL_BRIDGE_FUNC(void, syncDataQueue,')
    sync = cpp[start:end]
    command = header[header.index('  class Command {'):header.index('\nprivate:\n  Bridge()')]
    statics = header[header.index('  static inline WriterChannel*'):header.index('#if defined(REMIX_BRIDGE_CLIENT)', header.index('  static inline WriterChannel*'))]
    definitions = cpp[cpp.index('#define DECL_COMMAND_FUNC'):]
    fixture = (ROOT / 'tests/ipc_baseline_support.cpp').read_text(encoding='utf-8')
    bridge = '''namespace BridgeId { struct Device {}; struct Module {}; }
template<typename BridgeId> class Bridge {
using DataT = uint32_t;
public:
static void syncDataQueue(size_t, bool);
static const WriterChannel& getWriterChannel() { return *s_pWriterChannel; }
static void install(WriterChannel* channel) { s_pWriterChannel = channel; s_cmdUID = 0; }
''' + command + statics + '''};
#define DECL_BRIDGE_FUNC(RETURN_T, NAME, ...) \\
template<typename BridgeId> RETURN_T Bridge<BridgeId>::NAME(__VA_ARGS__)
''' + sync + '\n' + definitions
    output.mkdir(parents=True, exist_ok=True)
    (output / 'ipc_baseline.cpp').write_text(fixture.replace('// INSERT_PRODUCTION_CONTROL_FLOW', bridge), encoding='utf-8')
    sources = {'util_bridgecommand.h': header, 'util_bridgecommand.cpp': cpp}
    manifest = {'scope': 'production Command ctor/dtor, serialization methods and syncDataQueue; deterministic queue/semaphore/peer adapters',
                'source_sha256': {n: hashlib.sha256(t.encode()).hexdigest() for n, t in sources.items()}}
    (output / 'source-manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, default=ROOT / '.deps/dxvk-remix')
    parser.add_argument('--output', type=Path, default=ROOT / '.deps/ipc-baseline')
    args = parser.parse_args()
    generate(args.source, args.output)
